            r = random_float_between(0.0f, 1.0f);
            x19 = FastTweenColor((*(int *)&hoven_troll_burst_color_a_from), (*(int *)&hoven_troll_burst_color_a_to), r);
            r = random_float_between(0.0f, 1.0f);
