            Moby *h;
            d->helper->draw_dist = (*(unsigned short *)&m->draw_dist);
            d->helper->visible = 1;
            h = d->helper;
            qcopy(&h->pos, &m->pos);
            qcopy(&h->rot, &m->rot);
