            f20 = FastSubRots(fast_atan2(u[0], u[1]), moby->rot.z);
            f2 = -fast_atan2(vec_length_xy(u), u[2]);
            if (f20 > 1.5707964f) f20 = 1.5707964f;
            else if (f20 < -1.5707964f) f20 = -1.5707964f;
            if (f2 > 0.5235988f) f2 = 0.5235988f;
